CREATE TABLE IF NOT EXISTS routines(id TEXT PRIMARY KEY,agent TEXT NOT NULL REFERENCES agents(id),name TEXT NOT NULL,prompt TEXT NOT NULL,next_at INTEGER NOT NULL,interval_ms INTEGER,enabled INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,trigger TEXT NOT NULL DEFAULT 'schedule',observation_revision INTEGER NOT NULL DEFAULT 1 CHECK(observation_revision>0)) STRICT;
CREATE TABLE IF NOT EXISTS routine_runs(routine TEXT NOT NULL REFERENCES routines(id),scheduled_at INTEGER,turn TEXT PRIMARY KEY REFERENCES turns(id),missed INTEGER NOT NULL,source TEXT NOT NULL DEFAULT 'scheduled',UNIQUE(routine,scheduled_at)) STRICT;
CREATE TABLE IF NOT EXISTS coordination(seq INTEGER PRIMARY KEY AUTOINCREMENT,turn TEXT NOT NULL REFERENCES turns(id),owner TEXT NOT NULL REFERENCES agents(id),target TEXT NOT NULL REFERENCES agents(id),kind TEXT NOT NULL,prompt TEXT NOT NULL,call TEXT NOT NULL,child TEXT REFERENCES turns(id)) STRICT;
CREATE TABLE IF NOT EXISTS script_permissions(agent TEXT PRIMARY KEY REFERENCES agents(id),enabled INTEGER NOT NULL,revision INTEGER NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS script_commands(id TEXT PRIMARY KEY,request TEXT NOT NULL,result TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS workflows(id TEXT PRIMARY KEY,agent TEXT NOT NULL REFERENCES agents(id),name TEXT NOT NULL,revision INTEGER NOT NULL,deleted INTEGER NOT NULL DEFAULT 0 CHECK(deleted IN(0,1))) STRICT;
CREATE TABLE IF NOT EXISTS workflow_versions(workflow TEXT NOT NULL REFERENCES workflows(id),revision INTEGER NOT NULL,graph TEXT NOT NULL,PRIMARY KEY(workflow,revision)) STRICT;
CREATE TABLE IF NOT EXISTS workflow_schedules(workflow TEXT PRIMARY KEY REFERENCES workflows(id),revision INTEGER NOT NULL,next_at INTEGER NOT NULL,interval_ms INTEGER,input TEXT NOT NULL,enabled INTEGER NOT NULL CHECK(enabled IN(0,1))) STRICT;
CREATE TABLE IF NOT EXISTS workflow_occurrences(workflow TEXT NOT NULL REFERENCES workflows(id),scheduled_at INTEGER NOT NULL,run TEXT REFERENCES workflow_runs(id),missed INTEGER NOT NULL,reason TEXT,PRIMARY KEY(workflow,scheduled_at)) STRICT;
CREATE TABLE IF NOT EXISTS workflow_webhooks(workflow TEXT PRIMARY KEY REFERENCES workflows(id),route TEXT UNIQUE NOT NULL,secret TEXT NOT NULL,revision INTEGER NOT NULL,enabled INTEGER NOT NULL CHECK(enabled IN(0,1))) STRICT;
CREATE TABLE IF NOT EXISTS workflow_runs(id TEXT PRIMARY KEY,workflow TEXT NOT NULL REFERENCES workflows(id),version INTEGER NOT NULL,agent TEXT NOT NULL REFERENCES agents(id),graph TEXT NOT NULL,input TEXT NOT NULL,last TEXT NOT NULL,cursor TEXT NOT NULL,steps INTEGER NOT NULL DEFAULT 0,revision INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL CHECK(status IN('ready','waiting','approval','done','failed','cancelled')),error TEXT,created TEXT NOT NULL,retry_settings TEXT) STRICT;
CREATE TABLE IF NOT EXISTS workflow_steps(run TEXT NOT NULL REFERENCES workflow_runs(id),seq INTEGER NOT NULL,node TEXT NOT NULL,turn TEXT UNIQUE REFERENCES turns(id),model TEXT,status TEXT NOT NULL CHECK(status IN('waiting','approval','done','failed','cancelled')),detail TEXT,settings TEXT,parallel_group INTEGER,parallel_branch INTEGER,PRIMARY KEY(run,seq)) STRICT;
CREATE TABLE IF NOT EXISTS flow_runs(root_turn TEXT PRIMARY KEY REFERENCES turns(id),routine TEXT NOT NULL REFERENCES routines(id),graph TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS flow_steps(root_turn TEXT NOT NULL REFERENCES flow_runs(root_turn),agent TEXT NOT NULL REFERENCES agents(id),turn TEXT UNIQUE REFERENCES turns(id),status TEXT NOT NULL CHECK(status IN('waiting','queued','done','failed','skipped')),result TEXT NOT NULL,PRIMARY KEY(root_turn,agent)) STRICT;
